import{Ct as e,Et as t,Tt as n,kt as r}from"./app-p182cZ-5.js";var i=JSON.parse(`{"path":"/02-Python%E7%BC%96%E7%A8%8B%E5%9F%BA%E7%A1%80.html","title":"Week 2 Python 编程基础","lang":"zh-CN","frontmatter":{"description":"Week 2 Python 编程基础 本章导读 时长：3 节课，每节 45 分钟 数据：data/02-python/stock_price.csv、data/02-python/supermarket_sales.csv、data/02-python/breast_cancer.csv 你将学到：用 Python 标准库 csv、statistics...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Week 2 Python 编程基础\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://zhouxianzhong.cn/courses/python-data-analysis/02-Python%E7%BC%96%E7%A8%8B%E5%9F%BA%E7%A1%80.html"}],["meta",{"property":"og:site_name","content":"Vibe Programming × Python 数据分析"}],["meta",{"property":"og:title","content":"Week 2 Python 编程基础"}],["meta",{"property":"og:description","content":"Week 2 Python 编程基础 本章导读 时长：3 节课，每节 45 分钟 数据：data/02-python/stock_price.csv、data/02-python/supermarket_sales.csv、data/02-python/breast_cancer.csv 你将学到：用 Python 标准库 csv、statistics..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"git":{},"autoDesc":true,"filePathRelative":"02-Python编程基础.md"}`),a={name:`02-Python编程基础.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="week-2-python-编程基础" tabindex="-1"><a class="header-anchor" href="#week-2-python-编程基础"><span>Week 2 Python 编程基础</span></a></h1><blockquote><p><strong>本章导读</strong> 时长：3 节课，每节 45 分钟 数据：<code>data/02-python/stock_price.csv</code>、<code>data/02-python/supermarket_sales.csv</code>、<code>data/02-python/breast_cancer.csv</code> 你将学到：用 Python 标准库 <code>csv</code>、<code>statistics</code>、<code>math</code> 读取 CSV，掌握变量、容器、条件、循环、函数、异常和调试 本周不引入 pandas 本周产出：<code>projects/&lt;姓名&gt;/02-stock.py</code>、<code>projects/&lt;姓名&gt;/02-supermarket.py</code>、<code>projects/&lt;姓名&gt;/02-breast-cancer.py</code></p></blockquote><p>本周三节课不按“先讲完所有语法，再做题目”的顺序。每一节都从一个具体数据问题开始，先引入刚好够用的概念，再用真实数据练习。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">看数据问题 → 引入概念 → 最小代码 → 自己试 → 应用到数据 → DSH 审查 → 验收</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><ol><li>第 1 节课：从一个价格列表开始，统计股票价格；</li><li>第 2 节课：从循环到函数和字典，汇总超市分店销售额；</li><li>第 3 节课：把脏数据讲清楚，安全处理乳腺癌数据中的异常值。</li></ol><p><strong>本周使用 DSH 的固定顺序：先理解计划，再检查命令，小步执行，验证结果。</strong> DSH 可以生成代码，但你必须能解释每一行。它说“写好了”不等于“做对了”，要看真实输出；它要执行命令时，先读命令本身。本周代码只允许使用标准库，出现 <code>pandas</code> 就是红线；原始 <code>data/</code> 目录只读，学生代码只写入 <code>projects/&lt;姓名&gt;/</code>。</p><h2 id="_1-第-1-节课-从一个价格列表开始-45-分钟" tabindex="-1"><a class="header-anchor" href="#_1-第-1-节课-从一个价格列表开始-45-分钟"><span>1. 第 1 节课 从一个价格列表开始（45 分钟）</span></a></h2><p>建议流程：先看示例，再自己跑通，最后复盘验收。</p><h3 id="_1-1-今天的数据与问题" tabindex="-1"><a class="header-anchor" href="#_1-1-今天的数据与问题"><span>1.1 今天的数据与问题</span></a></h3><p>数据：<code>data/02-python/stock_price.csv</code>，252 行 x 2 列，字段 <code>Date</code>、<code>Price</code>。</p><p>问题：读取 <code>Price</code> 列，计算平均价格、最高价格、最低价格和上涨天数。</p><p>先看计划：</p><pre class="mermaid-raw"><code>flowchart LR
    A[读取文件] --&gt; B[逐行取出 Price]
    B --&gt; C[转成 float]
    C --&gt; D[用 statistics 算平均]
    D --&gt; E[用 max/min 找极值]
    E --&gt; F[相邻两日比较，数上涨天数]</code></pre><p>计划里没有“修改原文件”和“安装 pandas”。这两件事本周都不做。</p><h3 id="_1-2-变量和基本类型" tabindex="-1"><a class="header-anchor" href="#_1-2-变量和基本类型"><span>1.2 变量和基本类型</span></a></h3><p>变量是给一个值起的名字，不是这个值本身。可以把它想成储物格上的标签：<code>price</code> 是标签，<code>23.02</code> 是格子里放的东西。Python 中每个值都有类型，类型决定它能做什么运算。</p><p>写代码前先记三个工具：<code>print()</code> 把结果打印到屏幕；<code>type()</code> 返回一个值的类型；<code>#</code> 后面的文字是注释，只给人看，Python 不执行。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">price <span class="token operator">=</span> <span class="token number">23.02</span>          <span class="token comment"># float，小数</span></span>
<span class="line">days <span class="token operator">=</span> <span class="token number">252</span>             <span class="token comment"># int，整数</span></span>
<span class="line">stock_name <span class="token operator">=</span> <span class="token string">&quot;PF&quot;</span>      <span class="token comment"># str，文本</span></span>
<span class="line">is_trading_day <span class="token operator">=</span> <span class="token boolean">True</span>  <span class="token comment"># bool，布尔</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">type</span><span class="token punctuation">(</span>price<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">type</span><span class="token punctuation">(</span>days<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">type</span><span class="token punctuation">(</span>stock_name<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">type</span><span class="token punctuation">(</span>is_trading_day<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/01-variable-types.py" target="_blank" rel="noopener noreferrer">01-variable-types.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">&lt;class &#39;float&#39;&gt;</span>
<span class="line">&lt;class &#39;int&#39;&gt;</span>
<span class="line">&lt;class &#39;str&#39;&gt;</span>
<span class="line">&lt;class &#39;bool&#39;&gt;</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>本周还会用到另外几种容器类型：</p><table><thead><tr><th>类型</th><th>中文名</th><th>示例</th><th>特点</th></tr></thead><tbody><tr><td><code>None</code></td><td>空值</td><td><code>None</code></td><td>表示“没有值”或“转换失败”</td></tr><tr><td><code>list</code></td><td>列表</td><td><code>[23.02, 23.15]</code></td><td>有序，可增删</td></tr><tr><td><code>tuple</code></td><td>元组</td><td><code>(&quot;2024-01-02&quot;, 23.02)</code></td><td>有序，创建后不改</td></tr><tr><td><code>dict</code></td><td>字典</td><td><code>{&quot;A&quot;: 106200.37}</code></td><td>按名字找值</td></tr><tr><td><code>set</code></td><td>集合</td><td><code>{&quot;A&quot;, &quot;B&quot;, &quot;C&quot;}</code></td><td>不重复</td></tr></tbody></table><p>四条规则：</p><ul><li>CSV 读进来的内容默认是 <code>str</code>，算数前必须转成数字；</li><li>变量名要说明用途，不要叫 <code>a</code>、<code>b</code>、<code>c</code>；</li><li>数字和字符串不能直接相加，先看 <code>type()</code>，再看报错；</li><li>容器类型会在具体用到时再展开，不在这一节一次背完。</li></ul><p><strong>自己试 1：</strong> 新建 <code>quantity = 5</code> 和 <code>unit_price = 12.5</code>，打印 <code>quantity * unit_price</code> 和它的 <code>type()</code>。先猜类型，再运行。</p><h3 id="_1-3-数字运算和-round" tabindex="-1"><a class="header-anchor" href="#_1-3-数字运算和-round"><span>1.3 数字运算和 <code>round()</code></span></a></h3><p>这一节先认识四个运算：<code>/</code> 是普通除法，结果可能是小数；<code>//</code> 是向下取整；<code>%</code> 是取余数；<code>round(x, 2)</code> 保留两位小数，用于显示，不改变原来的数据。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token number">10</span> <span class="token operator">/</span> <span class="token number">3</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token number">10</span> <span class="token operator">//</span> <span class="token number">3</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token number">10</span> <span class="token operator">%</span> <span class="token number">3</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">round</span><span class="token punctuation">(</span><span class="token number">23.969999</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/02-number-operations.py" target="_blank" rel="noopener noreferrer">02-number-operations.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">3.3333333333333335</span>
<span class="line">3</span>
<span class="line">1</span>
<span class="line">23.97</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><code>/</code> 是普通除法，结果可能是 <code>float</code></li><li><code>//</code> 是向下取整</li><li><code>%</code> 是取余数</li><li><code>round(x, 2)</code> 保留两位小数，用于显示，不改变原来的数据</li></ul><h3 id="_1-4-列表和-for-循环" tabindex="-1"><a class="header-anchor" href="#_1-4-列表和-for-循环"><span>1.4 列表和 <code>for</code> 循环</span></a></h3><p>价格是一串有序、可以增删的数字，用 <code>list</code>。列表编号从 0 开始，所以第一个元素是 <code>prices[0]</code>，最后一个是 <code>prices[-1]</code>。<code>len(列表)</code> 返回元素个数；<code>列表.append(值)</code> 在末尾增加一个元素。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">prices <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">23.02</span><span class="token punctuation">,</span> <span class="token number">23.15</span><span class="token punctuation">,</span> <span class="token number">23.50</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>prices<span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>prices<span class="token punctuation">[</span><span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">prices<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token number">23.80</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">len</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/03-list-basics.py" target="_blank" rel="noopener noreferrer">03-list-basics.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">23.02</span>
<span class="line">23.5</span>
<span class="line">[23.02, 23.15, 23.5, 23.8]</span>
<span class="line">4</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>for</code> 循环让程序重复执行同一段代码。<code>for price in prices:</code> 的意思是：依次把列表中的每个元素放进变量 <code>price</code>，执行缩进块；列表里有几个元素，缩进块就执行几次。<code>break</code> 会立即结束整个循环，后面的元素不再处理。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">prices <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">23.02</span><span class="token punctuation">,</span> <span class="token number">23.15</span><span class="token punctuation">,</span> <span class="token number">23.50</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">total <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">for</span> price <span class="token keyword">in</span> prices<span class="token punctuation">:</span></span>
<span class="line">    total <span class="token operator">=</span> total <span class="token operator">+</span> price</span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>total<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/04-list-for-sum.py" target="_blank" rel="noopener noreferrer">04-list-for-sum.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">69.67</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>累加前先准备 <code>total = 0</code>，这个初始值必须在循环外设置。</p><p><strong>自己试 2：</strong> 写一个循环，只打印大于 <code>23.1</code> 的价格。先说出你预期会看到哪几个数，再运行。</p><h3 id="_1-5-用-statistics-算均值-用-min-max-找极值" tabindex="-1"><a class="header-anchor" href="#_1-5-用-statistics-算均值-用-min-max-找极值"><span>1.5 用 <code>statistics</code> 算均值，用 <code>min</code> / <code>max</code> 找极值</span></a></h3><p><code>import statistics</code> 把标准库模块 statistics 加载进来，之后用 <code>statistics.mean(...)</code> 调用它的平均值函数。<code>min()</code> 和 <code>max()</code> 是 Python 自带函数。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> statistics</span>
<span class="line"></span>
<span class="line">prices <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token number">23.02</span><span class="token punctuation">,</span> <span class="token number">23.15</span><span class="token punctuation">,</span> <span class="token number">23.50</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>statistics<span class="token punctuation">.</span>mean<span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">min</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token builtin">max</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/05-statistics-mean-min-max.py" target="_blank" rel="noopener noreferrer">05-statistics-mean-min-max.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">23.223333333333333</span>
<span class="line">23.02</span>
<span class="line">23.5</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>mean</code> 是平均值，<code>min</code> / <code>max</code> 是最小值、最大值。这些函数都来自标准库，不需要 pandas。</p><h3 id="_1-6-读取-csv-的-price-列" tabindex="-1"><a class="header-anchor" href="#_1-6-读取-csv-的-price-列"><span>1.6 读取 CSV 的 <code>Price</code> 列</span></a></h3><p>现在把前面的概念接到真实文件上。这里会用到几个新语法：<code>import csv</code> 加载 CSV 模块；<code>with open(path, encoding=&quot;utf-8-sig&quot;, newline=&quot;&quot;) as f:</code> 打开文件并在结束时自动关闭；<code>csv.DictReader(f)</code> 把每行读成以表头为键的字典；<code>row[&quot;Price&quot;]</code> 按列名取这一行的值；<code>float(...)</code> 把文本转成小数。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"><span class="token keyword">import</span> statistics</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/stock_price.csv&quot;</span></span>
<span class="line">prices <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">        prices<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token builtin">float</span><span class="token punctuation">(</span>row<span class="token punctuation">[</span><span class="token string">&quot;Price&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;样本量:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;平均价格:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>statistics<span class="token punctuation">.</span>mean<span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;最高价格:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span><span class="token builtin">max</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;最低价格:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span><span class="token builtin">min</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/06-stock-csv.py" target="_blank" rel="noopener noreferrer">06-stock-csv.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/stock_price.csv" target="_blank" rel="noopener noreferrer">stock_price.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">样本量: 252</span>
<span class="line">平均价格: 19.3</span>
<span class="line">最高价格: 23.97</span>
<span class="line">最低价格: 14.5</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>关键点：</p><ul><li><code>csv.DictReader</code> 把每一行读成字典，表头是键，所以用 <code>row[&quot;Price&quot;]</code></li><li>CSV 读出来是字符串，<code>float(row[&quot;Price&quot;])</code> 把它转成小数</li><li><code>encoding=&quot;utf-8-sig&quot;</code> 自动去掉文件开头的 BOM，避免列名变成 <code>\\ufeffPrice</code></li></ul><p><strong>自己试 3：</strong> 把代码改成只打印前 3 个价格。用 <code>break</code> 在第三次后停止循环。</p><h3 id="_1-7-数上涨天数" tabindex="-1"><a class="header-anchor" href="#_1-7-数上涨天数"><span>1.7 数上涨天数</span></a></h3><p>上涨天数表示相邻两天比较后、后一天高于前一天的次数。这里需要两个新工具：<code>range(1, len(prices))</code> 生成从 1 到 <code>len(prices) - 1</code> 的整数序列；<code>if prices[i] &gt; prices[i - 1]:</code> 表示条件成立时才执行缩进块，<code>&gt;</code> 是比较大小。<code>up_days += 1</code> 是 <code>up_days = up_days + 1</code> 的简写。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/stock_price.csv&quot;</span></span>
<span class="line">prices <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">        prices<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token builtin">float</span><span class="token punctuation">(</span>row<span class="token punctuation">[</span><span class="token string">&quot;Price&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">up_days <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">for</span> i <span class="token keyword">in</span> <span class="token builtin">range</span><span class="token punctuation">(</span><span class="token number">1</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>prices<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">if</span> prices<span class="token punctuation">[</span>i<span class="token punctuation">]</span> <span class="token operator">&gt;</span> prices<span class="token punctuation">[</span>i <span class="token operator">-</span> <span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">:</span></span>
<span class="line">        up_days <span class="token operator">+=</span> <span class="token number">1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;上涨天数:&quot;</span><span class="token punctuation">,</span> up_days<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/07-stock-up-days.py" target="_blank" rel="noopener noreferrer">07-stock-up-days.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/stock_price.csv" target="_blank" rel="noopener noreferrer">stock_price.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">上涨天数: 122</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>重点解释：</p><ul><li><code>range(1, len(prices))</code>：从第 2 个价格开始，和前一天比较</li><li><code>len(prices)</code> 是 252，所以循环比较 251 次，不是 252 次</li><li><code>prices[i - 1]</code>：紧邻的前一天价格</li></ul><h3 id="_1-8-dsh-vibe-loop-与验收" tabindex="-1"><a class="header-anchor" href="#_1-8-dsh-vibe-loop-与验收"><span>1.8 DSH vibe loop 与验收</span></a></h3><p>把这节课的脚本交给 DSH 审查，问它三个问题：</p><ol><li>为什么 <code>float(row[&quot;Price&quot;])</code> 不能省略？</li><li>为什么上涨天数不是 252？</li><li>如果 <code>statistics.mean(prices)</code> 报错，最可能是什么原因？</li></ol><p>DSH 回答后，你必须用自己的话复述一遍，能复述才继续下一步。</p><ul><li>[ ] 能说出 <code>int</code>、<code>float</code>、<code>str</code>、<code>bool</code> 的区别</li><li>[ ] 能解释 <code>list</code> 为什么适合存价格序列</li><li>[ ] 能用 <code>for</code> 循环把列表加总</li><li>[ ] <code>stock_price.csv</code> 脚本只用 <code>csv</code> 和 <code>statistics</code>，没有 pandas</li><li>[ ] 能输出 252 行、平均 19.3、最高 23.97、最低 14.5、上涨天数 122</li><li>[ ] 能解释“上涨天数比较 251 次，不是 252 次”</li></ul><h2 id="_2-第-2-节课-从循环到函数和字典-45-分钟" tabindex="-1"><a class="header-anchor" href="#_2-第-2-节课-从循环到函数和字典-45-分钟"><span>2. 第 2 节课 从循环到函数和字典（45 分钟）</span></a></h2><p>建议流程：先看示例，再自己跑通，最后复盘验收。</p><h3 id="_2-1-今天的数据与问题" tabindex="-1"><a class="header-anchor" href="#_2-1-今天的数据与问题"><span>2.1 今天的数据与问题</span></a></h3><p>数据：<code>data/02-python/supermarket_sales.csv</code>，1000 行 x 17 列。主要字段：<code>Branch</code>、<code>City</code>、<code>Customer type</code>、<code>Product line</code>、<code>Unit price</code>、<code>Quantity</code>、<code>Total</code>、<code>Rating</code>。</p><p>问题：写一个函数，计算各 <code>Branch</code> 的总销售额。</p><p>先看计划：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">打开文件 → csv.DictReader 逐行读取 → 取出 Branch 和 Total → Total 转 float → 累加到字典 → 输出 A/B/C 三个分店的总销售额</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>Total</code> 读进来是字符串，例如 <code>&#39;548.9715&#39;</code>，必须先转成 <code>float</code>，否则字典累加会变成字符串拼接。</p><h3 id="_2-2-条件分支" tabindex="-1"><a class="header-anchor" href="#_2-2-条件分支"><span>2.2 条件分支</span></a></h3><p><code>if</code> 处理一个条件；<code>elif</code> 表示“否则如果”，可以接多个条件；<code>else</code> 是以上都不满足时的兜底。判断从上往下，先命中的分支执行，后面的不再检查。比较运算符 <code>&gt;</code>、<code>&gt;=</code>、<code>&lt;</code>、<code>==</code> 的结果是 <code>True</code> 或 <code>False</code>。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">rating <span class="token operator">=</span> <span class="token number">9.1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">if</span> rating <span class="token operator">&gt;=</span> <span class="token number">8.0</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;高评分&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">elif</span> rating <span class="token operator">&gt;=</span> <span class="token number">6.0</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;中评分&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">else</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;低评分&quot;</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/08-rating-if-elif-else.py" target="_blank" rel="noopener noreferrer">08-rating-if-elif-else.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">高评分</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><strong>自己试 4：</strong> 把 <code>rating</code> 改成 <code>7.5</code>，预测会输出什么；再把 <code>elif rating &gt;= 6.0</code> 改成 <code>elif rating &gt;= 7.5</code>，再看结果。</p><h3 id="_2-3-字典" tabindex="-1"><a class="header-anchor" href="#_2-3-字典"><span>2.3 字典</span></a></h3><p>要保存“分店 → 总销售额”，需要一个能把名字和数值配对的容器，这就是 <code>dict</code>。它像查字典：键是“分店名”，值是“累计销售额”。<code>{&quot;A&quot;: 0.0}</code> 创建一个字典；<code>branch_totals[&quot;A&quot;]</code> 用键 <code>A</code> 取出对应值。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">branch_totals <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token string">&quot;A&quot;</span><span class="token punctuation">:</span> <span class="token number">0.0</span><span class="token punctuation">,</span> <span class="token string">&quot;B&quot;</span><span class="token punctuation">:</span> <span class="token number">0.0</span><span class="token punctuation">,</span> <span class="token string">&quot;C&quot;</span><span class="token punctuation">:</span> <span class="token number">0.0</span><span class="token punctuation">}</span></span>
<span class="line">branch_totals<span class="token punctuation">[</span><span class="token string">&quot;A&quot;</span><span class="token punctuation">]</span> <span class="token operator">+=</span> <span class="token number">10.0</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>branch_totals<span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>branch_totals<span class="token punctuation">[</span><span class="token string">&quot;B&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/09-dict-basics.py" target="_blank" rel="noopener noreferrer">09-dict-basics.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">{&#39;A&#39;: 10.0, &#39;B&#39;: 0.0, &#39;C&#39;: 0.0}</span>
<span class="line">0.0</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>当键第一次出现时，要先用 <code>get(key, 0.0)</code> 给默认值，否则直接累加会报 <code>KeyError</code>。</p><h3 id="_2-4-csv-dictreader-逐行读取" tabindex="-1"><a class="header-anchor" href="#_2-4-csv-dictreader-逐行读取"><span>2.4 <code>csv.DictReader</code> 逐行读取</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/supermarket_sales.csv&quot;</span></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">print</span><span class="token punctuation">(</span>row<span class="token punctuation">[</span><span class="token string">&quot;Branch&quot;</span><span class="token punctuation">]</span><span class="token punctuation">,</span> row<span class="token punctuation">[</span><span class="token string">&quot;Total&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">break</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/10-csv-dictreader-first-row.py" target="_blank" rel="noopener noreferrer">10-csv-dictreader-first-row.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/supermarket_sales.csv" target="_blank" rel="noopener noreferrer">supermarket_sales.csv</a></p><p>输出（只打印第一行，然后停止）：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">A 548.9715</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p><code>csv.DictReader</code> 会用第一行表头作为键，后面的每一行变成字典。用它逐行处理，先想清楚每一行要做什么。</p><pre class="mermaid-raw"><code>flowchart LR
    A[open 文件] --&gt; B[csv.DictReader 逐行读取]
    B --&gt; C{还有下一行吗}
    C -- 是 --&gt; D[取出 Branch 和 Total]
    D --&gt; E[累加到对应分店]
    E --&gt; C
    C -- 否 --&gt; F[输出各 Branch 总销售额]</code></pre><h3 id="_2-5-先写循环版汇总" tabindex="-1"><a class="header-anchor" href="#_2-5-先写循环版汇总"><span>2.5 先写循环版汇总</span></a></h3><p>这里用到三个新语法：<code>dict.get(key, 0.0)</code> 在键存在时返回值，不存在时返回默认值 <code>0.0</code>；<code>sorted(字典)</code> 返回按键排序后的列表；<code>f&quot;...&quot;</code> 是 f-string，用大括号插入变量，<code>:.2f</code> 表示保留两位小数。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/supermarket_sales.csv&quot;</span></span>
<span class="line">branch_totals <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">        branch <span class="token operator">=</span> row<span class="token punctuation">[</span><span class="token string">&quot;Branch&quot;</span><span class="token punctuation">]</span></span>
<span class="line">        total <span class="token operator">=</span> <span class="token builtin">float</span><span class="token punctuation">(</span>row<span class="token punctuation">[</span><span class="token string">&quot;Total&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">        branch_totals<span class="token punctuation">[</span>branch<span class="token punctuation">]</span> <span class="token operator">=</span> branch_totals<span class="token punctuation">.</span>get<span class="token punctuation">(</span>branch<span class="token punctuation">,</span> <span class="token number">0.0</span><span class="token punctuation">)</span> <span class="token operator">+</span> total</span>
<span class="line"></span>
<span class="line"><span class="token keyword">for</span> branch <span class="token keyword">in</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span>branch_totals<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string-interpolation"><span class="token string">f&quot;Branch </span><span class="token interpolation"><span class="token punctuation">{</span>branch<span class="token punctuation">}</span></span><span class="token string">: </span><span class="token interpolation"><span class="token punctuation">{</span>branch_totals<span class="token punctuation">[</span>branch<span class="token punctuation">]</span><span class="token punctuation">:</span><span class="token format-spec">.2f</span><span class="token punctuation">}</span></span><span class="token string">&quot;</span></span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/11-supermarket-loop-total.py" target="_blank" rel="noopener noreferrer">11-supermarket-loop-total.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/supermarket_sales.csv" target="_blank" rel="noopener noreferrer">supermarket_sales.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Branch A: 106200.37</span>
<span class="line">Branch B: 106197.67</span>
<span class="line">Branch C: 110568.71</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-6-封装成函数" tabindex="-1"><a class="header-anchor" href="#_2-6-封装成函数"><span>2.6 封装成函数</span></a></h3><p>函数是把一段可重复使用的逻辑打包，并给它一个明确输入和输出。<code>def sales_by_branch(path)</code> 定义了一个函数：输入是文件路径，输出是各分店销售额字典。函数内部只负责计算，<code>return</code> 把结果交给调用者；打印应该留在调用处。<code>result.items()</code> 返回 <code>(键, 值)</code> 组成的序列；<code>for branch, total in sorted(result.items())</code> 同时把键和值放进两个变量。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token function">sales_by_branch</span><span class="token punctuation">(</span>path<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    totals <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line">    <span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">        reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">            branch <span class="token operator">=</span> row<span class="token punctuation">[</span><span class="token string">&quot;Branch&quot;</span><span class="token punctuation">]</span></span>
<span class="line">            total <span class="token operator">=</span> <span class="token builtin">float</span><span class="token punctuation">(</span>row<span class="token punctuation">[</span><span class="token string">&quot;Total&quot;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">            totals<span class="token punctuation">[</span>branch<span class="token punctuation">]</span> <span class="token operator">=</span> totals<span class="token punctuation">.</span>get<span class="token punctuation">(</span>branch<span class="token punctuation">,</span> <span class="token number">0.0</span><span class="token punctuation">)</span> <span class="token operator">+</span> total</span>
<span class="line">    <span class="token keyword">return</span> totals</span>
<span class="line"></span>
<span class="line">result <span class="token operator">=</span> sales_by_branch<span class="token punctuation">(</span><span class="token string">&quot;data/02-python/supermarket_sales.csv&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> branch<span class="token punctuation">,</span> total <span class="token keyword">in</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span>result<span class="token punctuation">.</span>items<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span>branch<span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>total<span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/12-supermarket-function.py" target="_blank" rel="noopener noreferrer">12-supermarket-function.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/supermarket_sales.csv" target="_blank" rel="noopener noreferrer">supermarket_sales.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">A 106200.37</span>
<span class="line">B 106197.67</span>
<span class="line">C 110568.71</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>自己试 5：</strong> 复制 <code>sales_by_branch()</code>，改写成 <code>sales_by_city()</code>，把 <code>Branch</code> 换成 <code>City</code>。先写出你预计的输出，再运行。</p><h3 id="_2-7-tuple-和-set-什么时候用" tabindex="-1"><a class="header-anchor" href="#_2-7-tuple-和-set-什么时候用"><span>2.7 <code>tuple</code> 和 <code>set</code> 什么时候用</span></a></h3><p>本节课主线上只需要 <code>list</code> 和 <code>dict</code>，但要知道另外两个容器什么时候合适：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line">one_day <span class="token operator">=</span> <span class="token punctuation">(</span><span class="token string">&quot;2024-01-02&quot;</span><span class="token punctuation">,</span> <span class="token number">23.02</span><span class="token punctuation">)</span>   <span class="token comment"># tuple：一行固定记录</span></span>
<span class="line">branches <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token string">&quot;A&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;B&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;C&quot;</span><span class="token punctuation">}</span>        <span class="token comment"># set：不重复的分店名</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/13-tuple-set.py" target="_blank" rel="noopener noreferrer">13-tuple-set.py</a></p><ul><li><code>tuple</code> 适合“日期 + 价格”这种固定组合，创建后不修改</li><li><code>set</code> 适合“有哪些城市”这种去重问题</li></ul><h3 id="_2-8-dsh-vibe-loop-与验收" tabindex="-1"><a class="header-anchor" href="#_2-8-dsh-vibe-loop-与验收"><span>2.8 DSH vibe loop 与验收</span></a></h3><p>先自己写 <code>sales_by_branch()</code>，再让 DSH 审查。DSH 给出修改版后，逐行说明它改了什么、为什么改；说不出来，就让它重新解释。</p><ul><li>[ ] 能解释 <code>if</code> / <code>elif</code> / <code>else</code> 的执行顺序</li><li>[ ] 能说明 <code>dict</code> 为什么适合“分店 → 总销售额”</li><li>[ ] 能用 <code>csv.DictReader</code> 逐行读取 <code>data/02-python/supermarket_sales.csv</code></li><li>[ ] <code>sales_by_branch()</code> 返回字典，而不是只在函数里打印</li><li>[ ] 输出 A、B、C 三个分店总销售额，结果与数据一致</li><li>[ ] 能解释 <code>totals.get(branch, 0.0)</code> 的作用</li><li>[ ] 全程没有 pandas，DSH 修改过的代码能解释</li></ul><h2 id="_3-第-3-节课-把脏数据讲清楚-45-分钟" tabindex="-1"><a class="header-anchor" href="#_3-第-3-节课-把脏数据讲清楚-45-分钟"><span>3. 第 3 节课 把脏数据讲清楚（45 分钟）</span></a></h2><p>建议流程：先看示例，再自己跑通，最后复盘验收。</p><h3 id="_3-1-今天的数据与问题" tabindex="-1"><a class="header-anchor" href="#_3-1-今天的数据与问题"><span>3.1 今天的数据与问题</span></a></h3><p>数据：<code>data/02-python/breast_cancer.csv</code>，699 行 x 11 列。主要字段：<code>Id</code>、<code>Cl.thickness</code>、<code>Cell.size</code>、<code>Cell.shape</code>、<code>Bare.nuclei</code>、<code>Bl.cromatin</code>、<code>Normal.nucleoli</code>、<code>Mitoses</code>、<code>Class</code>。</p><p>问题：<code>Bare.nuclei</code> 里有非数字标记，不能直接 <code>int()</code>。课程要求识别 <code>?</code>；本仓库当前文件把这 16 个缺失写作 <code>NA</code>，代码必须两种都处理。</p><p>先看计划：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">读取文件 → 审计行数、列数、表头 → 找出 Bare.nuclei 的非数字值 → 用 try/except 保护转换 → 统计时先剔除异常值 → 输出描述统计</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_3-2-先审计" tabindex="-1"><a class="header-anchor" href="#_3-2-先审计"><span>3.2 先审计</span></a></h3><p><code>reader.fieldnames</code> 是表头列表；<code>list(reader)</code> 把所有行一次读进列表，这样能马上知道总行数。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/breast_cancer.csv&quot;</span></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">    fieldnames <span class="token operator">=</span> reader<span class="token punctuation">.</span>fieldnames</span>
<span class="line">    rows <span class="token operator">=</span> <span class="token builtin">list</span><span class="token punctuation">(</span>reader<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;总记录数:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>rows<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;列数:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>fieldnames<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;列名:&quot;</span><span class="token punctuation">,</span> fieldnames<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/14-breast-cancer-audit.py" target="_blank" rel="noopener noreferrer">14-breast-cancer-audit.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/breast_cancer.csv" target="_blank" rel="noopener noreferrer">breast_cancer.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">总记录数: 699</span>
<span class="line">列数: 11</span>
<span class="line">列名: [&#39;Id&#39;, &#39;Cl.thickness&#39;, &#39;Cell.size&#39;, &#39;Cell.shape&#39;, &#39;Marg.adhesion&#39;, &#39;Epith.c.size&#39;, &#39;Bare.nuclei&#39;, &#39;Bl.cromatin&#39;, &#39;Normal.nucleoli&#39;, &#39;Mitoses&#39;, &#39;Class&#39;]</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>审计是第一步。没看过表头和行数就做统计，等于没检查材料就开始写结论。</p><h3 id="_3-3-找出-和-na" tabindex="-1"><a class="header-anchor" href="#_3-3-找出-和-na"><span>3.3 找出 <code>?</code> 和 <code>NA</code></span></a></h3><p><code>row[&quot;Bare.nuclei&quot;].strip()</code> 去掉首尾空格，避免 <code>NA</code> 因带空格而漏判。<code>值 in 集合</code> 判断该值是否在集合中。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/breast_cancer.csv&quot;</span></span>
<span class="line">missing <span class="token operator">=</span> <span class="token number">0</span></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">if</span> row<span class="token punctuation">[</span><span class="token string">&quot;Bare.nuclei&quot;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token keyword">in</span> <span class="token punctuation">{</span><span class="token string">&quot;?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;NA&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;&quot;</span><span class="token punctuation">}</span><span class="token punctuation">:</span></span>
<span class="line">            missing <span class="token operator">+=</span> <span class="token number">1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;Bare.nuclei 缺失/异常标记:&quot;</span><span class="token punctuation">,</span> missing<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/15-breast-cancer-missing.py" target="_blank" rel="noopener noreferrer">15-breast-cancer-missing.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/breast_cancer.csv" target="_blank" rel="noopener noreferrer">breast_cancer.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Bare.nuclei 缺失/异常标记: 16</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>处理规则：</p><ul><li>先统计有多少个 <code>?</code> / <code>NA</code>，再决定怎么处理</li><li>统计数值时剔除这些行，并在结果里报告样本量</li><li>不要悄悄把 <code>?</code> 当成 0，那是编造数据</li></ul><h3 id="_3-4-用-try-except-处理转换失败" tabindex="-1"><a class="header-anchor" href="#_3-4-用-try-except-处理转换失败"><span>3.4 用 <code>try</code> / <code>except</code> 处理转换失败</span></a></h3><p>当 <code>int(&quot;?&quot;)</code> 无法转换时，Python 会抛出 <code>ValueError</code>。<code>try</code> 先尝试正常执行，<code>except ValueError</code> 只捕获这一种预期内的错误。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">to_int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">try</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token builtin">int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">except</span> ValueError<span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">None</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>to_int<span class="token punctuation">(</span><span class="token string">&quot;5&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>to_int<span class="token punctuation">(</span><span class="token string">&quot;?&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span>to_int<span class="token punctuation">(</span><span class="token string">&quot;NA&quot;</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/16-to-int-try-except.py" target="_blank" rel="noopener noreferrer">16-to-int-try-except.py</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">5</span>
<span class="line">None</span>
<span class="line">None</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>只捕获 <code>ValueError</code>，不写空 <code>except:</code>。空捕获会连代码本身的 bug 一起藏起来。</p><h3 id="_3-5-print-和断点调试" tabindex="-1"><a class="header-anchor" href="#_3-5-print-和断点调试"><span>3.5 <code>print</code> 和断点调试</span></a></h3><p>调试是观察程序运行时的状态，不是把报错藏起来。<code>print</code> 适合快速查看一个值，<code>breakpoint()</code> 适合在复杂循环里暂停并逐步检查。<code>repr(value)</code> 显示值的原始表示，能看出普通 <code>print</code> 看不到的空格或引号。</p><p>先用 <code>print</code> 看转换前的内容：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">to_int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;转换前:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">repr</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">try</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token builtin">int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">except</span> ValueError<span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">None</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/17-debug-repr.py" target="_blank" rel="noopener noreferrer">17-debug-repr.py</a></p><p>如果数据多了，再临时加断点：</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">def</span> <span class="token function">to_int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    breakpoint<span class="token punctuation">(</span><span class="token punctuation">)</span>   <span class="token comment"># 调试完成后必须删除</span></span>
<span class="line">    <span class="token keyword">try</span><span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token builtin">int</span><span class="token punctuation">(</span>value<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">except</span> ValueError<span class="token punctuation">:</span></span>
<span class="line">        <span class="token keyword">return</span> <span class="token boolean">None</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/20-debug-breakpoint.py" target="_blank" rel="noopener noreferrer">20-debug-breakpoint.py</a></p><p>运行后程序会停在 <code>breakpoint()</code>，在 <code>(Pdb)</code> 提示符后输入 <code>value</code> 看当前值，输入 <code>n</code> 执行下一行，输入 <code>q</code> 退出。VS Code 里也可以点行号左侧加红点断点，用调试按钮运行。</p><p>调试只用于找问题，<code>print</code> 和 <code>breakpoint()</code> 改完代码后要删掉，不能留进提交文件。</p><h3 id="_3-6-load-column-和基础描述统计" tabindex="-1"><a class="header-anchor" href="#_3-6-load-column-和基础描述统计"><span>3.6 <code>load_column()</code> 和基础描述统计</span></a></h3><p><code>continue</code> 表示跳过本轮循环，直接处理下一行；在 <code>load_column()</code> 里用它跳过异常值。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"><span class="token keyword">import</span> statistics</span>
<span class="line"></span>
<span class="line"><span class="token keyword">def</span> <span class="token function">load_column</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> column<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    values <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="line">    <span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">        reader <span class="token operator">=</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span></span>
<span class="line">        <span class="token keyword">for</span> row <span class="token keyword">in</span> reader<span class="token punctuation">:</span></span>
<span class="line">            raw <span class="token operator">=</span> row<span class="token punctuation">[</span>column<span class="token punctuation">]</span><span class="token punctuation">.</span>strip<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">if</span> raw <span class="token keyword">in</span> <span class="token punctuation">{</span><span class="token string">&quot;&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;?&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;NA&quot;</span><span class="token punctuation">}</span><span class="token punctuation">:</span></span>
<span class="line">                <span class="token keyword">continue</span></span>
<span class="line">            <span class="token keyword">try</span><span class="token punctuation">:</span></span>
<span class="line">                values<span class="token punctuation">.</span>append<span class="token punctuation">(</span><span class="token builtin">int</span><span class="token punctuation">(</span>raw<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">            <span class="token keyword">except</span> ValueError<span class="token punctuation">:</span></span>
<span class="line">                <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;无法转换:&quot;</span><span class="token punctuation">,</span> <span class="token builtin">repr</span><span class="token punctuation">(</span>raw<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">return</span> values</span>
<span class="line"></span>
<span class="line">columns <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&quot;Cl.thickness&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Cell.size&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Cell.shape&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;Bare.nuclei&quot;</span><span class="token punctuation">]</span></span>
<span class="line"><span class="token keyword">for</span> column <span class="token keyword">in</span> columns<span class="token punctuation">:</span></span>
<span class="line">    values <span class="token operator">=</span> load_column<span class="token punctuation">(</span><span class="token string">&quot;data/02-python/breast_cancer.csv&quot;</span><span class="token punctuation">,</span> column<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span></span>
<span class="line">        column<span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;n=&quot;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>values<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;mean=&quot;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>statistics<span class="token punctuation">.</span>mean<span class="token punctuation">(</span>values<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">2</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;min=&quot;</span><span class="token punctuation">,</span> <span class="token builtin">min</span><span class="token punctuation">(</span>values<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">        <span class="token string">&quot;max=&quot;</span><span class="token punctuation">,</span> <span class="token builtin">max</span><span class="token punctuation">(</span>values<span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/18-load-column-stats.py" target="_blank" rel="noopener noreferrer">18-load-column-stats.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/breast_cancer.csv" target="_blank" rel="noopener noreferrer">breast_cancer.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Cl.thickness n= 699 mean= 4.42 min= 1 max= 10</span>
<span class="line">Cell.size n= 699 mean= 3.13 min= 1 max= 10</span>
<span class="line">Cell.shape n= 699 mean= 3.21 min= 1 max= 10</span>
<span class="line">Bare.nuclei n= 683 mean= 3.54 min= 1 max= 10</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意 <code>Bare.nuclei</code> 的 <code>n=683</code>，不是 699。16 个 <code>?</code> / <code>NA</code> 被明确剔除并报告，这才叫处理异常值。</p><p><strong>自己试 6：</strong> 把 <code>load_column()</code> 里的 <code>continue</code> 删掉，预测会发生什么；只改回一行，再运行验证。</p><h3 id="_3-7-统计-class-样本数" tabindex="-1"><a class="header-anchor" href="#_3-7-统计-class-样本数"><span>3.7 统计 <code>Class</code> 样本数</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> csv</span>
<span class="line"></span>
<span class="line">path <span class="token operator">=</span> <span class="token string">&quot;data/02-python/breast_cancer.csv&quot;</span></span>
<span class="line">classes <span class="token operator">=</span> <span class="token punctuation">{</span><span class="token punctuation">}</span></span>
<span class="line"><span class="token keyword">with</span> <span class="token builtin">open</span><span class="token punctuation">(</span>path<span class="token punctuation">,</span> encoding<span class="token operator">=</span><span class="token string">&quot;utf-8-sig&quot;</span><span class="token punctuation">,</span> newline<span class="token operator">=</span><span class="token string">&quot;&quot;</span><span class="token punctuation">)</span> <span class="token keyword">as</span> f<span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">for</span> row <span class="token keyword">in</span> csv<span class="token punctuation">.</span>DictReader<span class="token punctuation">(</span>f<span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">        key <span class="token operator">=</span> row<span class="token punctuation">[</span><span class="token string">&quot;Class&quot;</span><span class="token punctuation">]</span></span>
<span class="line">        classes<span class="token punctuation">[</span>key<span class="token punctuation">]</span> <span class="token operator">=</span> classes<span class="token punctuation">.</span>get<span class="token punctuation">(</span>key<span class="token punctuation">,</span> <span class="token number">0</span><span class="token punctuation">)</span> <span class="token operator">+</span> <span class="token number">1</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&quot;Class 样本数:&quot;</span><span class="token punctuation">,</span> classes<span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/02-python/19-class-counts.py" target="_blank" rel="noopener noreferrer">19-class-counts.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/02-python/breast_cancer.csv" target="_blank" rel="noopener noreferrer">breast_cancer.csv</a></p><p>输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">Class 样本数: {&#39;0&#39;: 458, &#39;1&#39;: 241}</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>这里 <code>Class</code> 是字符串 <code>&#39;0&#39;</code> 和 <code>&#39;1&#39;</code>，所以字典键也是字符串。样本量相加等于 699。</p><h3 id="_3-8-dsh-vibe-loop-与验收" tabindex="-1"><a class="header-anchor" href="#_3-8-dsh-vibe-loop-与验收"><span>3.8 DSH vibe loop 与验收</span></a></h3><p>把脚本交给 DSH 审查，问它：</p><ol><li>为什么先识别 <code>?</code> / <code>NA</code>，再 <code>int()</code>？</li><li>剔除 16 行数据后，样本量变化对结论有什么影响？</li><li>为什么 <code>except ValueError</code> 不能改成空 <code>except:</code>？</li></ol><p>DSH 解释后，你写一句话说明自己的处理口径。</p><ul><li>[ ] 能审计出 699 行、11 列和完整表头</li><li>[ ] 能识别出 <code>Bare.nuclei</code> 的 16 个缺失标记（<code>?</code> 或 <code>NA</code>）</li><li>[ ] 能用 <code>try</code> / <code>except ValueError</code> 保护转换，且只捕获 <code>ValueError</code></li><li>[ ] 能解释 <code>print</code> 调试和断点调试的用途，并知道调试代码要删除</li><li>[ ] 描述统计输出包含样本量 <code>n</code>，<code>Bare.nuclei</code> 为 683</li><li>[ ] 能输出 <code>Class</code> 为 0 和 1 的样本数</li><li>[ ] 全程没有 pandas，能复述 DSH 给出的每行代码</li></ul><h2 id="_4-本周验证清单" tabindex="-1"><a class="header-anchor" href="#_4-本周验证清单"><span>4. 本周验证清单</span></a></h2><ul><li>[ ] 三个脚本保存在 <code>projects/&lt;姓名&gt;/</code>：<code>02-stock.py</code>、<code>02-supermarket.py</code>、<code>02-breast-cancer.py</code></li><li>[ ] 三个脚本都能从仓库根目录直接运行，路径都是 <code>data/02-python/...</code></li><li>[ ] 股票脚本输出 252 行、平均 19.3、最高 23.97、最低 14.5、上涨天数 122</li><li>[ ] 销售脚本输出 A、B、C 三个分店总销售额</li><li>[ ] 癌症脚本审计 699 行、11 列，识别 16 个 <code>?</code> / <code>NA</code></li><li>[ ] <code>Bare.nuclei</code> 统计时明确报告 <code>n=683</code></li><li>[ ] 三个脚本只使用 <code>csv</code>、<code>statistics</code>、<code>math</code>，没有 pandas</li><li>[ ] 每个脚本的每一行，学生都能解释</li><li>[ ] 使用 DSH 时按“先理解计划 → 检查命令 → 小步执行 → 验证结果”完成</li><li>[ ] <code>data/</code> 原始文件没有被修改</li></ul><h2 id="_5-常见错误与坑" tabindex="-1"><a class="header-anchor" href="#_5-常见错误与坑"><span>5. 常见错误与坑</span></a></h2><table><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td><code>TypeError: can only concatenate str</code></td><td>没把 CSV 里的数字转成 float/int</td><td>用 <code>float(row[&#39;Total&#39;])</code> 后再累加</td></tr><tr><td><code>ValueError: invalid literal for int()</code></td><td>遇到 <code>?</code>、<code>NA</code> 或空格</td><td>先识别异常值，再用 <code>try/except</code> 保护转换</td></tr><tr><td><code>KeyError: &#39;Bare.nuclei&#39;</code></td><td>表头有 BOM，或列名写错</td><td>用 <code>encoding=&#39;utf-8-sig&#39;</code>，先打印 <code>fieldnames</code></td></tr><tr><td>上涨天数写成 252</td><td>把每个价格都当成上涨起点</td><td>从 <code>range(1, len(prices))</code> 开始，只有 251 次比较</td></tr><tr><td><code>while</code> 一直运行</td><td>忘记更新循环变量</td><td>每次循环更新 <code>i</code>，或改用 <code>for</code></td></tr><tr><td>函数没有结果</td><td>只在函数里 <code>print</code>，没有 <code>return</code></td><td>函数返回字典，调用处再打印</td></tr><tr><td>字典报 <code>KeyError</code></td><td>第一次出现键时直接 <code>totals[branch] += ...</code></td><td>用 <code>totals.get(branch, 0.0)</code></td></tr><tr><td>把 <code>?</code> 当成 0</td><td>没审计异常值</td><td>先统计并剔除，报告 <code>n</code>，不编造数据</td></tr><tr><td>空 <code>except:</code> 吞掉错误</td><td>想“让它别报错”</td><td>只捕获具体异常，如 <code>ValueError</code></td></tr><tr><td>调试代码留在脚本里</td><td>加了 <code>print</code> / <code>breakpoint()</code> 后忘记删</td><td>调试完删除，再运行一次验证</td></tr><tr><td>脚本里出现 pandas</td><td>提示词没限制，或直接让 DSH 自由发挥</td><td>明确要求只用 <code>csv</code>、<code>statistics</code>、<code>math</code></td></tr><tr><td>DSH 说完成就相信</td><td>没有看命令和输出</td><td>自己运行、看结果、解释代码后再验收</td></tr><tr><td>结论只有数字没有样本量</td><td>统计前剔除了数据但没报告</td><td>每个统计都带 <code>n</code>，例如 <code>Bare.nuclei n=683</code></td></tr></tbody></table><h2 id="_6-作业" tabindex="-1"><a class="header-anchor" href="#_6-作业"><span>6. 作业</span></a></h2><ol><li>新建 <code>projects/&lt;姓名&gt;/02-stock.py</code>：读取 <code>data/02-python/stock_price.csv</code>，输出行数、平均价格、最高价格、最低价格、上涨天数；用一句话解释为什么上涨天数比较次数是 251。</li><li>新建 <code>projects/&lt;姓名&gt;/02-supermarket.py</code>：实现 <code>sales_by_branch()</code>，输出各 <code>Branch</code> 总销售额；再写一个 <code>sales_by_city()</code>，输出各 <code>City</code> 总销售额。</li><li>新建 <code>projects/&lt;姓名&gt;/02-breast-cancer.py</code>：审计 699 行、11 列，统计 <code>Bare.nuclei</code> 中 <code>?</code> / <code>NA</code> 的数量，用 <code>try/except</code> 保护转换，输出 <code>Cl.thickness</code>、<code>Cell.size</code>、<code>Cell.shape</code>、<code>Bare.nuclei</code> 的 <code>n</code>、<code>mean</code>、<code>min</code>、<code>max</code>，以及 <code>Class</code> 样本数。</li><li>三个脚本都让 DSH 审查一次，但审查后必须逐行解释 DSH 改动的内容；解释不出来，就让 DSH 重新解释，不能直接保存运行。</li><li>在三个脚本开头各写一行注释，说明“这个脚本回答什么问题、处理口径是什么”。</li></ol><h2 id="_7-参考写法" tabindex="-1"><a class="header-anchor" href="#_7-参考写法"><span>7. 参考写法</span></a></h2><p>本章借鉴了以下 GitHub 开源英文书的“小步示例 + 立即练习 + 数据应用”结构，未直接复制原文：</p><ul><li><a href="https://github.com/SoftUni/Programming-Basics-Book-Python-EN" target="_blank" rel="noopener noreferrer">SoftUni/Programming-Basics-Book-Python-EN</a></li><li><a href="https://github.com/AllenDowney/ThinkPython2" target="_blank" rel="noopener noreferrer">AllenDowney/ThinkPython2</a></li><li><a href="https://github.com/ehmatthes/pcc_3e" target="_blank" rel="noopener noreferrer">ehmatthes/pcc_3e</a></li><li><a href="https://github.com/csev/py4e" target="_blank" rel="noopener noreferrer">csev/py4e</a></li></ul><h2 id="评分要点" tabindex="-1"><a class="header-anchor" href="#评分要点"><span>评分要点</span></a></h2><table><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>基础语法</td><td>能区分 int/float/str/bool，能选择 list/dict/tuple/set</td></tr><tr><td>文件读取</td><td>只用标准库 <code>csv</code>，路径写 <code>data/02-python/...</code>，可运行</td></tr><tr><td>控制流</td><td>能解释条件分支、for/while，并避免死循环</td></tr><tr><td>函数</td><td><code>sales_by_branch()</code> 返回字典，调用后输出各分店销售额</td></tr><tr><td>异常处理</td><td>能识别 <code>?</code> / <code>NA</code>，用 <code>try/except ValueError</code> 保护转换</td></tr><tr><td>统计口径</td><td>描述统计带样本量，明确报告 <code>Bare.nuclei n=683</code></td></tr><tr><td>AI 协作</td><td>先理解计划、检查命令、小步执行、验证结果；DSH 生成的代码能解释</td></tr><tr><td>数据安全</td><td><code>data/</code> 未修改，代码只写入 <code>projects/&lt;姓名&gt;/</code>，全程无 pandas</td></tr></tbody></table>`,194)]])}var s=e(a,[[`render`,o]]);export{i as _pageData,s as default};